import {createManagement} from './management.js';
// Independent support service. Does not import or replace login, ERP or payment handlers.
import {createSupportTools} from './support.js';
const base=Deno.env.get('SUPABASE_URL'),service=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY'),publicKey=Deno.env.get('SUPABASE_ANON_KEY');
const cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization,apikey,content-type,x-client-info,x-support-session','Access-Control-Allow-Methods':'GET,POST,PUT,DELETE,OPTIONS','Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'};
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:cors});
const fail=(status,message)=>{throw Object.assign(Error(message),{status})};
async function body(req){const s=await req.text();if(s.length>16384)fail(413,'Solicitação muito grande.');try{const b=JSON.parse(s);if(!b||typeof b!=='object'||Array.isArray(b))throw Error();return b}catch{fail(400,'Dados inválidos.')}}
async function db(path,options={}){const r=await fetch(base+'/rest/v1/'+path,{...options,headers:{apikey:service,Authorization:'Bearer '+service,'Content-Type':'application/json',...options.headers}}),data=await r.json().catch(()=>null);if(!r.ok){if(data?.code==='23505')fail(409,'Esta identificação já está em uso. Escolha outra.');if(String(data?.message).includes('business_has_history'))fail(409,'A loja tem histórico e deve ser desativada.');fail(503,'Não foi possível consultar ou atualizar. Tente novamente.');}return data}
const rpc=(name,args)=>db('rpc/'+name,{method:'POST',body:JSON.stringify(args)});
const audit=(actor,action,business=null,session=null,target=null,details={})=>db('access_audit',{method:'POST',body:JSON.stringify({actor_id:actor,action,business_id:business,support_session_id:session,target_id:target,details})});
async function identity(req){const token=req.headers.get('authorization')?.match(/^Bearer ([^ ]+)$/i)?.[1];if(!token)fail(401,'Entre para continuar.');const r=await fetch(base+'/auth/v1/user',{headers:{apikey:publicKey,Authorization:'Bearer '+token}});if(!r.ok)fail(401,'Sua sessão expirou. Entre novamente.');const user=await r.json();let claims;try{claims=JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')))}catch{fail(401,'Sessão inválida.')}if(claims.sub!==user.id||!claims.session_id||!await rpc('business_auth_session_valid',{p_user:user.id,p_session:claims.session_id}))fail(401,'Sua sessão foi encerrada. Entre novamente.');return user}
const management=createManagement({db,rpc,base,service,json,fail,body,audit});
const tools=createSupportTools({db,rpc,body,json,fail,audit});
export async function handle(req){try{
 if(req.method==='OPTIONS')return new Response(null,{status:204,headers:cors});
 const route=new URL(req.url).pathname.split('/support-access')[1]||'/';
 if(route==='/login'&&req.method==='POST')return await management.login(req);
 const user=await identity(req),admin=(await db('platform_admins?select=user_id,display_name&user_id=eq.'+encodeURIComponent(user.id)+'&active=eq.true'))[0]||null;
 if(route==='/platform/support'&&req.method==='POST'){
  if(!admin)fail(403,'Acesso exclusivo do administrador da plataforma.');const b=await body(req);if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.business_id||''))fail(400,'Selecione um estabelecimento.');
  const shop=(await db('businesses?select=id&id=eq.'+b.business_id+'&active=eq.true'))[0];if(!shop)fail(404,'Estabelecimento indisponível.');
  const sessions=await db('support_sessions',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({actor_id:user.id,business_id:shop.id,purpose:'Atendimento pela área de suporte',write_enabled:true})});const s=sessions[0];
  await audit(user.id,'support.start',shop.id,s.id,null,{write_enabled:true,source:'support_workspace'});return json({session:s},201);
 }
 const managed=await management.platform(req,route,user,admin);if(managed)return managed;
 const response=await tools.platform(req,route,user,admin);if(response)return response;
 if(admin)fail(403,'Abra os chamados pela sua área de suporte.');
 const member=(await db('business_members?select=user_id,business_id,display_name,role,active,must_change_password&user_id=eq.'+encodeURIComponent(user.id)))[0];
 if(!member?.active)fail(403,'Acesso indisponível. Fale com o proprietário.');if(member.must_change_password)fail(428,'Troque a senha temporária para continuar.');
 const business=(await db('businesses?select=id,active&id=eq.'+member.business_id+'&active=eq.true'))[0];if(!business)fail(403,'Estabelecimento indisponível.');
 const access=await management.customer(req,route,user,member,business);if(access)return access;
 const result=await tools.customer(req,route,user,{m:member},business);if(result)return result;fail(404,'Opção não encontrada.');
}catch(e){return json({error:e.status?e.message:'Não foi possível concluir a solicitação de suporte.'},e.status||500)}}
Deno.serve(handle);

export function normalizeIdentifier(value){let v=String(value||'').trim();if(/^[\d.\/-]+$/.test(v))return v.replace(/\D/g,'');return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[\s_]+/g,'-')}
export function createManagement({db,rpc,base,service,json,fail,body,audit}){
 const uuid=v=>typeof v==='string'&&/^[a-f0-9-]{36}$/i.test(v);
 const identifier=v=>{const id=normalizeIdentifier(v);if(id&&!/^[a-z0-9][a-z0-9-]{2,59}$/.test(id))fail(400,'Use de 3 a 60 letras, números ou hífen; CNPJ pode ser digitado com pontuação.');return id};
 async function login(req){const b=await body(req),id=identifier(b.business_code),username=String(b.username||'').trim().toLowerCase();if(!username||typeof b.password!=='string'||b.password.length>128)fail(401,'Estabelecimento, usuário ou senha inválidos.');const code=await rpc('resolve_business_access',{p_identifier:id});if(!code)fail(401,'Estabelecimento, usuário ou senha inválidos.');const r=await fetch(base+'/functions/v1/auth-access/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({business_code:code,username,password:b.password})});return json(await r.json(),r.status)}
 async function save(req,id,user,platform){const b=await body(req),name=typeof b.name==='string'?b.name.trim():'';if(!name||name.length>100||(platform&&typeof b.active!=='boolean'))fail(400,'Confira o nome e a situação da empresa.');const alias=identifier(b.access_alias);await audit(user.id,'business.update.request',id);const result=await rpc('update_business_access',{p_business:id,p_name:name,p_alias:alias,p_active:platform?b.active:null});if(!result)fail(404,'Estabelecimento não encontrado.');await audit(user.id,'business.update',id,null,null,{name,access_alias:alias,active:result.active});return json({business:result})}
 async function platform(req,route,user,admin){if(!route.startsWith('/platform/businesses/')&&route!=='/platform/deletions')return null;if(!admin)fail(403,'Acesso exclusivo do administrador da plataforma.');
  if(route==='/platform/deletions'&&req.method==='GET')return json({deletions:await db('business_deletions?select=id,business_name,created_at&order=created_at.desc&limit=100')});
  const m=route.match(/^\/platform\/businesses\/([a-f0-9-]{36})(?:\/(cleanup))?$/i);if(!m)fail(404,'Estabelecimento não encontrado.');const id=m[1];
  if(req.method==='GET')return json({business:await rpc('business_delete_preview',{p_business:id})});if(req.method==='PUT')return await save(req,id,user,true);
  if(req.method==='DELETE'){const b=await body(req);if(b.confirmed!==true||typeof b.confirmation!=='string')fail(400,'Confirme o nome da empresa antes de excluir.');const preview=await rpc('business_delete_preview',{p_business:id});if(preview&&!preview.can_delete)fail(409,'Esta loja possui movimentações ou chamados. Use Desativar para preservar o histórico.');const job=await rpc('delete_empty_business',{p_business:id,p_actor:user.id,p_confirmation:b.confirmation});return json({deleted:true,recoverable:true})}
  fail(405,'Método não permitido.');
 }
 async function customer(req,route,user,member,business){if(route!=='/business-access')return null;if(member.role!=='admin')fail(403,'Somente o proprietário pode alterar a identificação.');if(req.method==='GET')return json({business:(await db('businesses?select=id,name,code,access_alias,active&id=eq.'+business.id))[0]});if(req.method==='PUT')return await save(req,business.id,user,false);fail(405,'Método não permitido.')}
 return {login,platform,customer};
}

const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
export function createSupportTools({db,rpc,body,json,fail,audit}){
 const trim=(s,max)=>typeof s==='string'?s.trim().slice(0,max):'';
 const states=['open','in_progress','waiting_customer','resolved'];
 const checked=(r)=>{if(r?.missing)fail(404,'Chamado não encontrado.');if(r?.conflict)fail(409,'O chamado foi alterado. Atualize antes de continuar.');if(r?.rate_limited)fail(429,'Limite de novos chamados atingido. Continue nos chamados existentes ou tente mais tarde.');return r};
 async function ticket(id,scope){const rows=await db('support_tickets?select=*&id=eq.'+id+scope);if(!rows[0])fail(404,'Chamado não encontrado.');return rows[0]}
 function query(url){const status=url.searchParams.get('status');if(status&&!states.includes(status)&&status!=='all')fail(400,'Filtro inválido.');let extra=status&&status!=='all'?'&status=eq.'+status:'';const business=url.searchParams.get('business');if(business){if(!UUID.test(business))fail(400,'Empresa inválida.');extra+='&business_id=eq.'+business}return extra}
 async function detail(req,t,side){const seen=side==='platform'?'support_seen_at':'customer_seen_at';await db('support_tickets?id=eq.'+t.id,{method:'PATCH',body:JSON.stringify({[seen]:new Date().toISOString()})});const messages=await db('support_messages?select=id,actor_name,side,body,created_at&ticket_id=eq.'+t.id+'&order=created_at.desc,id.desc&limit=201');return json({ticket:t,messages:messages.slice(0,200).reverse(),truncated:messages.length>200})}
 async function reply(req,t,user,name,side){const b=await body(req),message=trim(b.message,4001);if(message.length>4000||!UUID.test(b.request_key||''))fail(400,'Informe uma mensagem de até 4.000 caracteres.');if(side==='customer'&&!message)fail(400,'Escreva uma mensagem.');if(side==='platform'&&(!states.includes(b.status)||!Number.isInteger(b.version)))fail(400,'Confira a situação do chamado.');const result=checked(await rpc('support_reply',{p_ticket:t.id,p_actor:user.id,p_name:name,p_side:side,p_request:b.request_key,p_message:message||null,p_status:side==='platform'?b.status:null,p_version:side==='platform'?b.version:null}));await audit(user.id,'ticket.'+(side==='platform'?'support.update':'customer.reply'),t.business_id,null,t.id,{status:result.status});return json({ticket:result,email_pending:side==='customer'})}
 async function platform(req,route,user,admin){if(!route.startsWith('/platform/workspace')&&!route.startsWith('/platform/tickets'))return null;if(!admin)fail(403,'Acesso exclusivo do administrador da plataforma.');
 if(route==='/platform/workspace'&&req.method==='GET'){const result=await rpc('support_overview',{});const pending=await db('support_email_outbox?select=id&status=eq.awaiting_configuration&limit=1000');return json({...result,email:{configured:false,pending:pending.length,explanation:'Avisos por e-mail aguardam configuração. Os chamados já ficam disponíveis neste painel.'}})}
 if(route==='/platform/tickets'&&req.method==='GET'){const extra=query(new URL(req.url));return json({tickets:await db('support_tickets?select=*&order=updated_at.desc&limit=200'+extra)})}
 const match=route.match(/^\/platform\/tickets\/([a-f0-9-]{36})$/i);if(match){const t=await ticket(match[1],'');if(req.method==='GET'){await audit(user.id,'ticket.support.read',t.business_id,null,t.id);return await detail(req,t,'platform');}if(req.method==='POST')return await reply(req,t,user,admin.display_name,'platform')}
 fail(404,'Opção de suporte não encontrada.');}
 async function customer(req,route,user,ctx,business){if(route==='/presence'&&req.method==='POST'){if(!ctx.support){const b=await body(req);const allowed=['inicio','mesas','pedidos','caixa','produtos','estoque','compras','fornecedores','fichas','financeiro','relatorios','equipe','config','ajuda'];await rpc('support_heartbeat',{p_business:business.id,p_actor:user.id,p_name:ctx.m.display_name,p_role:ctx.m.role,p_route:allowed.includes(b.route)?b.route:''})}return json({ok:true})}
 if(!route.startsWith('/tickets'))return null;
 if(ctx.support)fail(403,'Abra os chamados pela sua área de suporte.');
 const scope='&business_id=eq.'+business.id+(ctx.m.role==='admin'?'':'&created_by=eq.'+user.id);
 if(route==='/tickets'&&req.method==='GET')return json({tickets:await db('support_tickets?select=*&order=updated_at.desc&limit=200'+scope)});
 if(route==='/tickets'&&req.method==='POST'){const b=await body(req),subject=trim(b.subject,121),message=trim(b.message,4001);if(subject.length<3||subject.length>120||!message||message.length>4000||!UUID.test(b.request_key||'')||!['error','question','suggestion','complaint'].includes(b.category)||!['normal','urgent'].includes(b.priority))fail(400,'Confira o assunto, tipo e mensagem do chamado.');const t=checked(await rpc('support_create_ticket',{p_business:business.id,p_actor:user.id,p_name:ctx.m.display_name,p_request:b.request_key,p_subject:subject,p_category:b.category,p_priority:b.priority,p_message:message}));await audit(user.id,'ticket.create',business.id,null,t.id);return json({ticket:t,email_pending:true},201)}
 const match=route.match(/^\/tickets\/([a-f0-9-]{36})$/i);if(match){const t=await ticket(match[1],scope);if(req.method==='GET')return await detail(req,t,'customer');if(req.method==='POST')return await reply(req,t,user,ctx.m.display_name,'customer')}
 fail(404,'Chamado não encontrado.');}
 return {platform,customer};
}
